# Write out Javascript output file
output_path = os.path.join("static", "js", "translations.js")
with open(output_path, "w", encoding="utf-8") as f:
    f.write("// SporoSentinel Global Localized Translation Dictionary\n")
    f.write("const translations = ")
    json.dump(translations, f, indent=4, ensure_ascii=False)
    f.write(";\n\n")
    
    # Map languages to web synthesis language codes
    speech_locales = {
        "en": "en-US", "hi": "hi-IN", "bn": "bn-IN", "mr": "mr-IN",
        "te": "te-IN", "ta": "ta-IN", "gu": "gu-IN", "kn": "kn-IN",
        "ml": "ml-IN", "pa": "pa-IN", "ur": "ur-PK", "or": "or-IN",
        "zh": "zh-CN", "es": "es-ES", "ar": "ar-SA", "fr": "fr-FR",
        "pt": "pt-BR", "ru": "ru-RU", "ja": "ja-JP"
    }
    f.write("const speechLocales = ")
    json.dump(speech_locales, f, indent=4)
    f.write(";\n")

print("translations.js generated successfully!")
